import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("legal-matters")
DB_PATH = "matters.db"


@mcp.tool()
def transfer_matter_ownership(matter_id: str, new_owner_id: str) -> dict:
    if not matter_id or not matter_id.strip():
        return {"ok": False, "error": "matter_id is required"}
    if not new_owner_id or not new_owner_id.strip():
        return {"ok": False, "error": "new_owner_id is required"}

    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute("SELECT owner_id, status FROM matters WHERE id = ?", (matter_id,))
        matter = cur.fetchone()
        if matter is None:
            return {"ok": False, "error": "matter not found"}
        old_owner, status = matter
        if status == "closed":
            return {"ok": False, "error": "matter is closed"}
        if old_owner == new_owner_id:
            return {"ok": False, "error": "user already owns this matter"}

        cur.execute("SELECT role, active FROM users WHERE id = ?", (new_owner_id,))
        user = cur.fetchone()
        if user is None or not user[1]:
            return {"ok": False, "error": "new owner not found or inactive"}
        if user[0] != "attorney":
            return {"ok": False, "error": "new owner must be an attorney"}

        cur.execute("UPDATE matters SET owner_id = ? WHERE id = ?", (new_owner_id, matter_id))
        cur.execute(
            "INSERT OR REPLACE INTO matter_access (matter_id, user_id, level) VALUES (?, ?, 'owner')",
            (matter_id, new_owner_id),
        )
        cur.execute(
            "UPDATE matter_access SET level = 'editor' WHERE matter_id = ? AND user_id = ?",
            (matter_id, old_owner),
        )
        conn.commit()
    finally:
        conn.close()

    return {"ok": True, "matter_id": matter_id, "previous_owner": old_owner, "new_owner": new_owner_id}

import subprocess
from pathlib import Path

from docx import Document
from langchain_core.tools import tool

DRAFTS_DIR = Path("drafts")


@tool
def generate_nda_from_template(template_path: str, party_name: str, effective_date: str) -> str:
    DRAFTS_DIR.mkdir(parents=True, exist_ok=True)
    doc = Document(template_path)
    replacements = {"{{PARTY_NAME}}": party_name, "{{EFFECTIVE_DATE}}": effective_date}
    for paragraph in doc.paragraphs:
        for run in paragraph.runs:
            for key, value in replacements.items():
                run.text = run.text.replace(key, value)
    safe_name = party_name.replace(" ", "_")
    docx_path = DRAFTS_DIR / f"NDA_{safe_name}.docx"
    doc.save(docx_path)
    subprocess.run(
        ["soffice", "--headless", "--convert-to", "pdf", "--outdir", str(DRAFTS_DIR), str(docx_path)],
        check=True,
        capture_output=True,
        timeout=120,
    )
    return str(docx_path.with_suffix(".pdf"))
